"""Generate a local submission draft without third-party Python dependencies."""
from pathlib import Path
from zipfile import ZipFile, ZIP_DEFLATED
from xml.sax.saxutils import escape
import argparse
p=argparse.ArgumentParser();p.add_argument('--first',default='firstname');p.add_argument('--last',default='lastname');p.add_argument('--url',default='PENDING: configure a reviewer-accessible Vercel, Netlify or Cloudflare Pages deployment');a=p.parse_args()
root=Path(__file__).resolve().parents[1]
sections=[('Nextplay — Task Studio','Software Development | Submission draft'),('Candidate',f'{a.first} {a.last}'),('Overview and design','A calm, responsive Kanban workspace with a lavender palette, clear hierarchy, compact task cards, and focused task editing. React and TypeScript handle the interface, dnd-kit provides drag interactions, and Supabase handles guest authentication and task storage once configured.'),('Live frontend',a.url + '\nPrivate owner preview (not the evaluator URL): https://nextplay-task-studio.trustworthystar1.chatgpt.site'),('Repository','https://github.com/alfatla002/New_Player_Games'),('Advanced features','Custom task labels with label filtering; case-insensitive title search and priority filtering; due-today and overdue indicators; task totals, completed totals, overdue totals and completion progress. Tasks can also be edited and deleted.'),('Local setup','Install Node.js 22+. Run npm ci. Copy .env.example to .env. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY using only the public key. Run the SQL schema below in Supabase. Enable anonymous sign-ins under Authentication. Run npm run dev. Run npm run build for production.'),('Authentication and security','The app reuses an existing Supabase session or calls signInAnonymously. Every task stores its owner user_id. Four RLS policies limit reads and writes to auth.uid(). Public unauthenticated database access is revoked. Never place a Supabase service-role key in this app. Separate browser profiles represent distinct guests; clearing browser data loses access to an anonymous account.'),('Verification and current limitations','Production build and unit tests passed. Browser checks could not launch because Chromium runtime libraries are missing and sudo requires a password. Supabase anonymous sign-in and the tasks table are operational. All 12 live API checks passed, covering distinct guest sessions, task creation, update, reload and deletion, cross-user read/update/delete denial, forged-owner insertion denial, ownership-transfer denial, unauthenticated access denial, and preservation of the original task after unauthorized requests. The temporary verification task was deleted. Without configuration, the application displays a clearly labeled browser-local demo. GitHub source is published using the authenticated candidate SSH key. Reviewer-accessible hosting remains pending. This draft is not ready to submit until these steps are completed.'),('Tradeoffs and future work','Updates become visible after a successful write/drop rather than through realtime subscriptions. Tasks use creation order rather than persisted manual ordering. Add cross-session conflict handling, guest account linking, team assignees, activity history, comments, and live automated security tests with more time.'),('Complete database schema',(root/'supabase/migrations/202611080001_tasks.sql').read_text())]
def paragraph(text,bold=False):
 return '<w:p><w:r>'+('<w:rPr><w:b/><w:color w:val="7561B9"/></w:rPr>' if bold else '')+'<w:t xml:space="preserve">'+escape(text)+'</w:t></w:r></w:p>'
body=''.join(paragraph(title,True)+''.join(paragraph(line) for line in text.splitlines())+paragraph('') for title,text in sections)
xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+body+'<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1080" w:right="1080" w:bottom="1080" w:left="1080"/></w:sectPr></w:body></w:document>'
output=root/'artifacts'/f'{a.first.lower()}_{a.last.lower()}_task_manager_assessment.docx';output.parent.mkdir(exist_ok=True)
with ZipFile(output,'w',ZIP_DEFLATED) as z:
 z.writestr('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>')
 z.writestr('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>')
 z.writestr('word/document.xml',xml)
print(output)
